#!/usr/bin/env bash
# inspect-apk.sh APK MANIFEST SDL3-DESCRIPTOR -- what an APK generated by
# botlish_android holds (RN-BOTLISH-ANDROID-SDL3-2048-PACKAGE-MILESTONE-1.md,
# "Gradle and APK"), checked from its bytes:
#
#   * the application ID, minimum and target API, the launchable Activity
#     (aapt2's badging), and SDL's Activity and the generated subclass in
#     classes.dex (dexdump);
#   * exactly arm64-v8a's three native libraries -- libSDL3.so, the Botlish
#     application library and libmain.so -- and no other ABI;
#   * each library's packaging (the generated project's: stored uncompressed
#     and 16 KiB-aligned in the zip, zipalign -P 16; or deflated, extracted
#     at installation) and its ELF: AArch64, every LOAD segment 16 KiB-aligned,
#     libmain.so needing the application library and libSDL3.so;
#   * the application library is the Botlish build the manifest describes,
#     as the Android build strips it (llvm-strip --strip-unneeded of the
#     manifest's file, byte for byte), and libSDL3.so the sdl3 package's.
#
# Prints one line per fact ("ok ..." or "FAIL ..."); exit status 1 on a
# failure. Needs ANDROID_HOME (build tools 35) and ANDROID_NDK_ROOT.
set -uo pipefail
apk=$(realpath "$1")
manifest=$(realpath "$2")
descriptor=$(realpath "$3")
bt=$(ls -d "$ANDROID_HOME"/build-tools/* | sort -V | tail -1)
ndkbin="$ANDROID_NDK_ROOT/toolchains/llvm/prebuilt/linux-x86_64/bin"
status=0
ok() { echo "ok $*"; }
fail() { echo "FAIL $*"; status=1; }
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
library=$(python3 -I -c 'import json,sys; print(json.load(open(sys.argv[1]))["library"])' "$manifest")
libdir=$(dirname "$manifest")

echo "apk $(basename "$apk") $(stat -c %s "$apk") bytes sha256 $(sha256sum "$apk" | cut -c1-16)"
badging=$("$bt/aapt2" dump badging "$apk" 2>/dev/null)
echo "$badging" | grep -E "^package:|^minSdkVersion|^sdkVersion|^targetSdkVersion|^launchable-activity|^native-code" | sed 's/^/  /'
echo "$badging" | grep -q "^native-code: 'arm64-v8a'$" && ok "native code: arm64-v8a only" || fail "native code is not arm64-v8a only"
listing=$(unzip -lv "$apk")
libs=$(echo "$listing" | awk '$8 ~ /^lib\// {print $8}' | sort)
expected=$(printf 'lib/arm64-v8a/%s\n' libSDL3.so "lib$library.so" libmain.so | sort)
[[ $libs == "$expected" ]] && ok "native libraries: $(echo $libs)" || fail "native libraries are $(echo $libs), not $(echo $expected)"
methods=$(echo "$listing" | awk '$8 ~ /^lib\// {print $2}' | sort -u)
if [[ $methods == Stored ]]; then
    "$bt/zipalign" -c -P 16 -v 4 "$apk" >"$work/zipalign.txt" 2>&1 && ok "zipalign -P 16: native libraries stored uncompressed, 16 KiB-aligned" \
        || { fail "zipalign -P 16: $(grep -v OK "$work/zipalign.txt" | head -3)"; }
else
    ok "native libraries deflated ($methods): extracted at installation"
fi
unzip -q -o "$apk" 'lib/*' classes.dex -d "$work"
for lib in libSDL3.so "lib$library.so" libmain.so; do
    f="$work/lib/arm64-v8a/$lib"
    machine=$("$ndkbin/llvm-readelf" -h "$f" | awk '/Machine:/ {print $2}')
    aligns=$("$ndkbin/llvm-readelf" -lW "$f" | awk '$1 == "LOAD" {print $NF}' | sort -u | tr '\n' ' ')
    [[ $machine == AArch64 && $aligns == "0x4000 " ]] && ok "$lib: AArch64, LOAD alignment $aligns" || fail "$lib: machine $machine, LOAD alignment $aligns"
done
needed=$("$ndkbin/llvm-readelf" -d "$work/lib/arm64-v8a/libmain.so" | sed -n 's/.*(NEEDED).*\[\(.*\)\]/\1/p' | sort | tr '\n' ' ')
[[ $needed == *"lib$library.so"* && $needed == *libSDL3.so* ]] && ok "libmain.so needs: $needed" || fail "libmain.so needs $needed"
"$ndkbin/llvm-nm" -D --defined-only "$work/lib/arm64-v8a/libmain.so" | grep -q " T SDL_main$" && ok "libmain.so defines SDL_main" || fail "libmain.so does not define SDL_main"
"$ndkbin/llvm-strip" --strip-unneeded -o "$work/expected.so" "$libdir/lib$library.so"
cmp -s "$work/expected.so" "$work/lib/arm64-v8a/lib$library.so" \
    && ok "lib$library.so is the manifest's library (sha256 $(python3 -I -c 'import json,sys; print(json.load(open(sys.argv[1]))["sha256"]["shared"][:16])' "$manifest")), as the Android build strips it" \
    || fail "lib$library.so is not the manifest's library stripped"
sdlsha=$(python3 -I -c 'import json,sys; print(json.load(open(sys.argv[1]))["library"]["sha256"])' "$descriptor")
sdlview=$(dirname "$(dirname "$descriptor")")
"$ndkbin/llvm-strip" --strip-unneeded -o "$work/sdl.so" "$sdlview/native/libSDL3.so"
if cmp -s "$sdlview/native/libSDL3.so" "$work/lib/arm64-v8a/libSDL3.so" || cmp -s "$work/sdl.so" "$work/lib/arm64-v8a/libSDL3.so"; then
    ok "libSDL3.so is the sdl3 package's (sha256 ${sdlsha:0:16})"
else
    fail "libSDL3.so is not the sdl3 package's"
fi
dex=$("$bt/dexdump" "$work/classes.dex" 2>/dev/null | sed -n "s/^  Class descriptor  : 'L\(.*\);'/\1/p")
echo "$dex" | grep -qx "org/libsdl/app/SDLActivity" && ok "classes.dex holds org.libsdl.app.SDLActivity" || fail "classes.dex lacks SDLActivity"
activity=$(echo "$badging" | sed -n "s/^launchable-activity: name='\([^']*\)'.*/\1/p")
echo "$dex" | grep -qx "$(echo "$activity" | tr . /)" && ok "classes.dex holds the launchable activity $activity" || fail "classes.dex lacks $activity"
exit $status
